using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioSelectionModeAvailabilityValidation {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static StudioModelEditor editor;static StudioModelDocument doc;static MashBoxStudioViewport view;static int checks;static bool pending=true;static readonly StudioModelEditor.ComponentMode[] modes={StudioModelEditor.ComponentMode.Object,StudioModelEditor.ComponentMode.Vertex,StudioModelEditor.ComponentMode.Edge,StudioModelEditor.ComponentMode.Face};
 static void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}static void All(string state){foreach(var mode in modes){Check(editor.CanSetToolbarComponentMode(mode),state+" mode enabled "+mode);editor.SetToolbarComponentMode(mode);Check(editor.ToolbarComponentMode==mode,state+" toolbar mode "+mode);var action=(StudioModelEditor.MarkingAction)Enum.Parse(typeof(StudioModelEditor.MarkingAction),mode.ToString());Check((bool)typeof(StudioModelEditor).GetMethod("MarkingActionEnabled",F).Invoke(editor,new object[]{action}),state+" marking action enabled "+mode);editor.ExecuteMarkingAction(action,null);Check(editor.ToolbarComponentMode==mode,state+" marking mode "+mode);}}
 public static void Run(){EditorApplication.delayCall+=Start;}
 static void Start(){try{editor=new StudioModelEditor(()=>view?.Repaint());All("No document");doc=ScriptableObject.CreateInstance<StudioModelDocument>();editor.Load(doc);All("Empty workspace");doc.nodes.Add(new StudioModelDocument.Node{name="Stem_Anchor",anchorType="Stem_Anchor",position=Vector3.right*10});var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var poly);doc.nodes.Add(new StudioModelDocument.Node{name="Cube",mesh=mesh,cutPolygons=poly,cutTriangles=mesh.triangles});editor.Load(doc);All("No selection");editor.SelectObject(0);All("Anchor selected");editor.SelectObject(1);All("Mesh selected");editor.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Edge);editor.SelectObject(0);Check(editor.ToolbarComponentMode==StudioModelEditor.ComponentMode.Edge,"Selecting transform retains chosen mode");editor.SelectObject(1);Check(editor.ToolbarComponentMode==StudioModelEditor.ComponentMode.Edge,"Selecting mesh retains chosen mode");var blend=typeof(StudioModelDocument.Node).GetField("blendShape",F|BindingFlags.Public);blend.SetValue(doc.nodes[1],Activator.CreateInstance(blend.FieldType,true));All("Protected blend shape selected");Check(!editor.CanEditComponents()&&!editor.CanDeleteSelection,"Protected geometry stays noneditable");blend.SetValue(doc.nodes[1],null);editor.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Object);editor.ExecuteMarkingAction(StudioModelEditor.MarkingAction.Clear,null);Check(editor.Active<0,"Object deselection clears editing target");editor.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Face);view=ScriptableObject.CreateInstance<MashBoxStudioViewport>();view.position=new Rect(80,80,700,550);view.Bind(editor.Scene);view.Show();view.LookAtDirect(Vector3.zero,Quaternion.Euler(12,25,0),2);SceneView.duringSceneGui+=Draw;view.MarkDirty(MashBoxStudioViewport.DirtyState.All);}catch(Exception e){Finish(e.ToString());}}
 static void Draw(SceneView scene){if(!pending||scene!=view||Event.current.type!=EventType.Repaint)return;pending=false;try{var point=HandleUtility.WorldToGUIPoint(Vector3.zero);typeof(StudioModelEditor).GetField("end",F).SetValue(editor,point);typeof(StudioModelEditor).GetMethod("PickCore",F).Invoke(editor,new object[]{view,new Rect(point,Vector2.zero),true});Check(editor.Active==1,"Component-first click acquires mesh");Check(editor.ToolbarComponentMode==StudioModelEditor.ComponentMode.Face,"Mesh acquisition retains Face mode");Check(editor.Components.Count==1,"Same click selects face");Finish("PASS "+checks+" selection-mode availability/acquisition checks");}catch(Exception e){Finish(e.ToString());}}
 static void Finish(string result){SceneView.duringSceneGui-=Draw;File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../selection-mode-availability-result.txt")),result);EditorApplication.delayCall+=()=>EditorApplication.Exit(result.StartsWith("PASS")?0:1);}
}
